#!/usr/bin/env python3
"""Classify documents in /app/documents as invoice/other, move them, and
write /app/invoices/summary.csv with filename,total_amount,vat_amount."""
import csv, os, re, shutil, subprocess

SRC, INV, OTH = '/app/documents', '/app/invoices', '/app/other'


def extract_text(path):
    if path.lower().endswith('.pdf'):
        out = subprocess.run(['pdftotext', '-layout', path, '-'],
                             capture_output=True, text=True).stdout
        if out.strip():
            return out
    return subprocess.run(['tesseract', path, '-', '--psm', '6'],
                          capture_output=True, text=True).stdout


def num(s):
    s = s.replace(' ', '').replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace(',', '') if s.rfind('.') > s.rfind(',') else s.replace('.', '').replace(',', '.')
    elif ',' in s:
        s = s.replace(',', '.') if re.search(r',\d{1,2}$', s) else s.replace(',', '')
    return float(s)


AMT = r'[-+]?\$?\s?\d[\d ,.]*\d|\d'


def amounts(line):
    return [num(m.group()) for m in re.finditer(r'\d[\d  ,.]*\d|\d', line.replace('$', ' '))]


def is_invoice(text):
    t = text.lower()
    if 'invoice' in t:
        return True
    return bool(re.search(r'\b(amount due|grand total|total due)\b', t))


def parse(text):
    total = vat = None
    lines = [l for l in text.splitlines() if l.strip()]
    # 1) summary row like: Total $ 6 236,77 $ 623,68 $ 6 860,45  (net, vat, gross)
    for l in lines:
        if re.match(r'\s*(grand\s+)?total\b', l, re.I) and l.count('$') >= 3:
            a = amounts(l)
            if len(a) >= 3:
                total, vat = a[-1], a[-2]
                return total, vat
    # 2) explicit VAT line
    for l in lines:
        m = re.search(r'\b(vat|tax|gst)\b[^0-9\-]{0,20}([\d ,.]+)', l, re.I)
        if m and not re.search(r'tax\s*id', l, re.I):
            try:
                v = num(m.group(2).strip())
                if vat is None:
                    vat = v
            except ValueError:
                pass
    # 3) Total / Grand Total / Total Price / Amount Due
    pats = [r'grand\s*total', r'total\s*price', r'\btotal\b', r'amount\s*(due|payable)', r'balance\s*due']
    for p in pats:
        for l in lines:
            if re.search(p, l, re.I) and not re.search(r'sub\s*-?\s*total', l, re.I):
                a = amounts(re.split(p, l, flags=re.I)[-1])
                if a:
                    total = a[-1] if len(a) == 1 else a[-1]
                    break
        if total is not None:
            break
    return total, vat


def main():
    rows = []
    for name in sorted(os.listdir(SRC)):
        path = os.path.join(SRC, name)
        if not os.path.isfile(path):
            continue
        text = extract_text(path)
        if is_invoice(text):
            total, vat = parse(text)
            rows.append([name, total or 0.0, vat or 0.0])
            shutil.move(path, os.path.join(INV, name))
        else:
            shutil.move(path, os.path.join(OTH, name))

    rows.sort(key=lambda r: r[0])
    with open(os.path.join(INV, 'summary.csv'), 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(['filename', 'total_amount', 'vat_amount'])
        for n, t, v in rows:
            w.writerow([n, f'{t:.2f}', f'{v:.2f}'])
        w.writerow(['total', f'{sum(r[1] for r in rows):.2f}',
                    f'{sum(r[2] for r in rows):.2f}'])


if __name__ == '__main__':
    main()
